import{_ as r,l,o as e,c as i,v as o,p as s,x as t,d as A,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"收敛与发展核算","description":"","frontmatter":{"title":"收敛与发展核算","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/convergence-accounting.md","filePath":"econ/convergence-accounting.md","lastUpdated":1789023840000}'),E={name:"econ/convergence-accounting.md"};function d(B,a,h,_,u,m){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="收敛与发展核算" tabindex="-1">收敛与发展核算 <a class="header-anchor" href="#收敛与发展核算" aria-label="Permalink to &quot;收敛与发展核算&quot;">​</a></h1><div class="epigraph"><p>索洛预测条件收敛；把穷国的落后写成「缺机器」还是「缺效率」，是核算问题，不是再写一遍运动方程。</p><footer>—— 对照 Solow 1956 的条件预测；Hall and Jones, QJE 1999 的发展核算</footer></div><p><a href="/econ/misallocation-tfp">上一课</a>（错配与 TFP）。让 \\(g\\) 可以来自人力资本与研发。若知识非竞争，穷国按理可以模仿，水平差应缩小；若壁垒使 \\(A\\) 不可移动，差会持久。本课的缺口不是再推内生增长，而是：用账户把跨国（或跨期）的人均产出差拆成资本、人力资本与剩余效率，并分清绝对收敛与条件收敛。货币课从下一课开始，增长主干在此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛：参数相同的经济走向同一稳态，穷的 \\(k\\) 增长更快——<strong>绝对收敛</strong>。参数不同则走向不同 \\(k^*\\)，只在控制 \\(s,n\\) 等之后才有<strong>条件收敛</strong>。内生增长可以取消收敛。经验上要先声明检验的是哪一句，不能把「东亚增长快」直接叫成索洛证实。</p><p>即便收敛方向清楚，水平差的来源仍未知。同样的 \\(K/L\\)，产出可以差一截：剩余进入 \\(A\\) 或效率。Hall 与 Jones（1999）一类发展核算把</p> \\[\\frac{Y}{L}=A\\cdot\\Bigl(\\frac{K}{Y}\\Bigr)^{\\alpha/(1-\\alpha)}h \\]<p>这类分解写成可计算形式（具体指数因写法而异），问有多少差来自资本强度、多少来自 \\(h\\)、多少来自 \\(A\\)。本课用核算，不用增长回归当因果。</p><p><span class="marginnote">Solow 1957 的残差是时间上的技术变化。发展核算是截面上的水平残差。都叫 \\(A\\)，不要当成已经识别了研发部门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>收敛：看 \\(\\Delta\\log y_i\\) 对初始 \\(\\log y_i\\) 的斜率。负斜率是 \\(\\beta\\) 收敛。\\(\\sigma\\) 收敛看离散度是否下降。条件收敛加入储蓄、人口、教育。Barro 式回归是简化式，卢卡斯批判对政策含义同样适用——那是后课，这里只警告系数不是结构 \\(s\\)。</p><p>发展核算：取生产函数，用观测的 \\(K\\)、\\(L\\)、教育代理 \\(h\\)，把 \\(A\\) 当残差。资本份额 \\(\\alpha\\) 通常取收入法中的资本份额，争议立刻进入分解。制度、误配置可以藏在 \\(A\\) 里，本课不把 \\(A\\) 命名为「文化」。</p>',12)),(e(),s(c,null,{default:t(()=>[p(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E7%BB%9D%E5%AF%B9%E6%94%B6%E6%95%9B%EF%BC%9A%E5%90%8C%E4%B8%80%E7%A8%B3%E6%80%81%22%5D%20--%3E%20TEST%5B%22%E6%88%AA%E9%9D%A2%E5%A2%9E%E9%95%BF%E5%9B%9E%E5%BD%92%22%5D%0A%20%20COND%5B%22%E6%9D%A1%E4%BB%B6%E6%94%B6%E6%95%9B%EF%BC%9A%E6%8E%A7%E5%88%B6%20s%2Cn%22%5D%20--%3E%20TEST%0A%20%20YL%5B%22%E4%BA%BA%E5%9D%87%E4%BA%A7%E5%87%BA%E5%B7%AE%22%5D%20--%3E%20ACC%5B%22%E5%8F%91%E5%B1%95%E6%A0%B8%E7%AE%97%22%5D%0A%20%20ACC%20--%3E%20K%5B%22%E8%B5%84%E6%9C%AC%E5%BC%BA%E5%BA%A6%22%5D%0A%20%20ACC%20--%3E%20H%5B%22%E4%BA%BA%E5%8A%9B%E8%B5%84%E6%9C%AC%22%5D%0A%20%20ACC%20--%3E%20A%5B%22%E5%89%A9%E4%BD%99%20A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>增长核算（时间差）与发展核算（截面差）公式同源、样本不同。中国或东亚的高速增长可以是 \\(K\\) 积累为主、 \\(A\\) 为辅，或反过来，取决于时段与数据；本课不写未核对的数字故事。</p><h3 id="误配置也是-a" tabindex="-1">误配置也是 A <a class="header-anchor" href="#误配置也是-a" aria-label="Permalink to &quot;误配置也是 A&quot;">​</a></h3><p>若资本与劳动困在低生产率企业，加总 \\(A\\) 下降，即使每家企业的技术不变。这是对「剩余=技术」的警告。微观误配置文献是扩展，主干仍用加总分解当第一刀。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>条件收敛来自递减报酬：离自己的 \\(k^*\\) 越远，边际产出越高。绝对不收敛来自 \\(s,n,g\\) 不同，或来自内生增长的多重路径。发展核算里 \\(A\\) 的大份额，表示「只运机器」不够；但 \\(A\\) 大也可能是 \\(K\\)、\\(h\\) 测错，或价格平减不一致——回到<a href="/econ/price-index-real">价格指数</a>的购买力平价篮子，不是外汇市场上的 CIP。</p><p>政策含义到此为止：核算指出差在哪一块，不指出哪一项改革的乘数。后课货币与周期处理的是 \\(y\\) 对 \\(y^*\\) 的短期偏离，假定 \\(y^*\\) 的水平已被增长课说明。</p><p>增长核算（时间差）与发展核算（截面差）公式同源、样本不同。东亚高速增长可以是 \\(K\\) 积累为主、\\(A\\) 为辅，或反过来，取决于时段与数据；本课不写未核对的数字故事。内生增长预测：若知识可模仿，水平差应缩小；若壁垒使 \\(A\\) 不可移动，差会持久——核算是对这句话的测量，不是再推一遍 \\(\\dot{A}\\)。</p><p><span class="marginnote">Barro 式收敛回归是简化式。系数不是结构 \\(s\\)，政策含义要等卢卡斯批判。本课只用它分清绝对与条件收敛的句子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收敛回归不是随机对照试验。殖民、地理、制度的工具变量争论不在本课展开。也不要把人均 GDP 差写成交易员看到的价差；本栏接到限价簿之前，价格是宏观指数与相对价格。资本份额 \\(\\alpha\\) 取收入法时，争议立刻进入 \\(A\\) 的大小。</p><p>后课默认：长期水平用 \\(K\\)、\\(h\\)、\\(A\\) 说话，短期缺口用 \\(u\\) 与 \\(y-y^*\\)。下一课引入货币作为支付手段，增长账暂时放下。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>索洛给条件收敛；绝对收敛需要参数相近。</li><li>发展核算把 \\(Y/L\\) 拆成资本、人力资本与剩余 \\(A\\)。</li><li>\\(A\\) 是残差，含技术、制度与误配置。</li><li>PPP 篮子进入截面比较；那不是 CIP。</li><li>货币中性建立在已经缩减、已经有 \\(y^*\\) 的世界上。</li><li>出处：Solow 1956/1957；Hall and Jones, QJE 1999。</li></ul>',13))])}const g=r(E,[["render",d]]);export{f as __pageData,g as default};
